<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import {computed,ref,watch,onMounted,onUnmounted} from 'vue';import {pluginSelectionPost} from '../../shared/danbooru-selection.mjs';import {Copy,ArrowRight,RefreshCw} from 'lucide-vue-next';import {useStudio,api} from '../store';import {tagSections,classifyPost,combineTags,animaTag} from '../../shared/anima-tags.mjs';
const browserRevision=ref(0),browserReady=ref(false),browserError=ref(''),browserRefreshing=ref(false);let browserTimer,browserRetries=0;async function refreshBrowser(){if(browserRefreshing.value)return;browserRefreshing.value=true;try{await api('danbooru/refresh',{});browserRetries=0;browserReady.value=false;browserError.value='';browserRevision.value++;}catch(e){browserError.value=e.message;s.notify('刷新未完成：'+e.message,'error');}finally{browserRefreshing.value=false;}}function watchBrowserLoad(){clearTimeout(browserTimer);browserTimer=setTimeout(()=>{if(browserReady.value)return;if(browserRetries++<1){browserRevision.value++;}else browserError.value='本地标签浏览器尚未响应，请刷新重试；若外网连接失败会在浏览器内显示具体原因。';},8000);}watch(browserRevision,watchBrowserLoad);function browserLoaded(event){try{if(event.target.contentDocument?.querySelector('#root button')){browserReady.value=true;browserError.value='';clearTimeout(browserTimer);}}catch{}}
const s=useStudio();watch(()=>s.lang,()=>{browserRevision.value++;});s.config.danbooru||={query:'',quality:'masterpiece, best quality, score_7, safe',excludeArtists:true,natural:'',overrides:{}};const prefs=computed(()=>s.config.danbooru),raw=ref('');
watch(()=>s.config.adultContentEnabled,async value=>{await api('settings',{adultContentEnabled:value});await refreshBrowser();});
prefs.value.liveTranslation??=true;const translations=ref({});let translateTimer;
const selected=computed({get:()=>prefs.value.selected,set:v=>prefs.value.selected=v});const sections=computed(()=>classifyPost(selected.value||{rawTags:raw.value},{...(selected.value?.pluginCategories||{}),...prefs.value.overrides}));const combined=computed(()=>selected.value?.pluginMultiple?selected.value.pluginOutputs.all:combineTags(sections.value,prefs.value));
const pluginOutputError=ref(''),pluginOutputBusy=ref(false);let selectionRun=0;
const translationStatus=ref('idle'),translationError=ref(''),translationProgress=ref(''),translationSources=ref('');let translationRun=0;
const tagExplanation=tag=>translations.value[tag]||s.tags.find(t=>t.en.toLowerCase()===tag.replaceAll('_',' ').toLowerCase())?.zh||(translationStatus.value==='error'?'未翻译 · 可重试':translationStatus.value==='loading'?'翻译中…':'等待翻译');
async function translateSelected(){const run=++translationRun;translationError.value='';if(!prefs.value.liveTranslation){translationStatus.value='idle';return;}const tags=[...new Set(Object.values(sections.value).flat())].filter(t=>!translations.value[t]);if(!tags.length){translationStatus.value='done';return;}translationStatus.value='loading';let unresolved=false;const sources=new Set();try{for(let i=0;i<tags.length;i+=12){if(run!==translationRun)return;translationProgress.value=`${i} / ${tags.length}`;const response=await fetch('/api/translate/tags',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tags:tags.slice(i,i+12)}),signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'翻译服务不可用');const valid={...data.translations};for(const tag of data.unresolved||[])delete valid[tag];Object.assign(translations.value,valid);unresolved||=!!data.partial;for(const source of data.sources||[])sources.add(source);}if(run===translationRun){translationStatus.value=unresolved?'error':'done';translationError.value=unresolved?'部分标签未译出，已自动尝试备用服务，可稍后重试。':'';translationSources.value=[...sources].join('、');translationProgress.value='';}}catch(e){if(run===translationRun){translationStatus.value='error';translationError.value=e.name==='TimeoutError'?'翻译响应超时，请重试。':e.message;}}}
watch([()=>combined.value,()=>prefs.value.liveTranslation],()=>{clearTimeout(translateTimer);++translationRun;translateTimer=setTimeout(translateSelected,350);},{immediate:true});
async function copy(text){try{await navigator.clipboard.writeText(text);s.notify('已复制');}catch{s.notify('复制失败，请选中文字复制。','error');}}
function apply(){s.p.positive=combined.value;s.tab='generate';s.notify('已导入正面提示词');}
async function pluginSelected(e){
 if(e.origin!==location.origin||e.source!==document.querySelector('.upstream-booru-browser')?.contentWindow)return;
 if(e.data?.type==='danbooru-ready'){browserReady.value=true;browserError.value='';clearTimeout(browserTimer);return;}
 if(e.data?.type!=='danbooru-selected')return;
 const run=++selectionRun,selection=e.data.selection||{},widgets=e.data.widgets||{},fusion=JSON.parse(widgets._tag_fusion||'{}');
 const id=selection.post_id||selection.selections?.[0]?.post_id||Object.values(fusion).flat()[0];
 pluginOutputError.value='';if(!id||selection.deselected){selected.value=null;pluginOutputBusy.value=false;return;}
 pluginOutputBusy.value=true;
 try{
  const [detail,output]=await Promise.all([fetch('/danbooru_anima/post/'+id).then(r=>r.json()),fetch('/api/danbooru/outputs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(widgets)}).then(r=>r.json())]);
  if(run!==selectionRun)return;if(!detail.success||!output.success)throw Error(detail.error||output.error||'标签输出失败');
  const post=detail.post||{};
  selected.value=pluginSelectionPost(post,output.outputs,{id,multiple:!!selection.selections?.length||Object.values(fusion).flat().length>0});
  Object.assign(translations.value,detail.translations||{});raw.value='';
 }catch(error){if(run===selectionRun){pluginOutputError.value=error.message;s.notify(error.message,'error');}}finally{if(run===selectionRun)pluginOutputBusy.value=false;}
}
onMounted(()=>{window.addEventListener('message',pluginSelected);watchBrowserLoad();});onUnmounted(()=>{clearTimeout(browserTimer);clearTimeout(translateTimer);window.removeEventListener('message',pluginSelected);});
function moveTag(tag,to){prefs.value.overrides[tag]=to;}
</script>
<template><div class="danbooru-workspace" v-resize-panels="{key:'danbooru',config:s.config,min:[300,300],labels:['调整浏览器与标签处理区宽度']}"><section class="card booru-browser"><div class="card-heading"><strong>{{ui("Danbooru 标签浏览器")}}</strong><div class="button-row"><button class="quiet" @click="s.config.settingsCategory='content';s.tab='settings'">{{ui("内容显示设置")}}</button><span class="muted">{{ui("原比例完整预览")}}</span><button class="secondary" :aria-busy="browserRefreshing||!browserReady" :disabled="browserRefreshing" @click="refreshBrowser" :title="ui(&quot;保留搜索条件并重新加载浏览器&quot;)"><RefreshCw :size="15"/>{{ui("刷新浏览器")}}</button></div></div><p v-if="!browserReady" class="booru-loading-note">{{ui(browserError||'正在加载本地标签浏览器… 外网连接会自动适配系统代理。')}}</p><iframe :key="browserRevision" :src="'/plugin/danbooru/index.html?reload='+browserRevision" @load="browserLoaded" class="upstream-booru-browser" :title="ui(&quot;Danbooru 标签浏览器&quot;)"/></section><aside class="booru-processing"><section class="card"><div class="card-heading"><strong>{{ui("组合后的正面提示词")}}</strong><small v-if="pluginOutputBusy||pluginOutputError">{{ui(pluginOutputBusy?'正在读取标签…':pluginOutputError)}}</small></div><div class="settings-body"><textarea :value="combined" rows="6" readonly :aria-label="ui(&quot;组合后的提示词&quot;)"/><div class="button-row"><button class="primary" @click="apply" :disabled="!combined.trim()">{{ui("一键导入正面提示词")}}<ArrowRight :size="16"/></button><button class="secondary" @click="copy(combined)"><Copy :size="15"/>{{ui("复制")}}</button></div><label class="inline-check"><input type="checkbox" v-model="prefs.liveTranslation"/>{{ui("实时中文翻译")}}</label><div v-if="prefs.liveTranslation" class="button-row"><small>{{ui(translationStatus==='loading'?'正在翻译 '+translationProgress:translationStatus==='done'?'标签翻译完成 · '+translationSources:translationError)}}</small><button class="quiet" @click="translateSelected" :disabled="translationStatus==='loading'" :aria-busy="translationStatus==='loading'"><RefreshCw :size="13"/>{{ui(translationStatus==='loading'?'翻译中…':'重新翻译')}}</button></div><div v-if="prefs.liveTranslation" class="booru-translated-tags"><span v-for="tag in Object.values(sections).flat()"><span>{{animaTag(tag)}}</span><small>{{tagExplanation(tag)}}</small></span></div><label class="inline-check"><input type="checkbox" v-model="prefs.excludeArtists"/>{{ui("去除画师 tag（默认开启）")}}</label></div></section><section class="card"><div class="card-heading"><strong>{{ui("提示词组合器")}}</strong></div><div class="settings-body"><label>{{ui("我的质量词")}}<textarea v-model="prefs.quality" rows="2"/></label><label>{{ui("补充自然语言描述")}}<textarea v-model="prefs.natural" rows="3" :placeholder="ui(&quot;复杂动作、视线和人物之间的位置关系……&quot;)"/></label><details><summary>{{ui("粘贴原始标签")}}</summary><textarea v-model="raw" @input="selected=null" rows="4" :placeholder="ui(&quot;用英文逗号或空格分隔标签&quot;)"/></details></div></section><section class="card tag-splitter"><div class="card-heading"><strong>{{ui("标签拆分器")}}</strong><small>{{ui(selected?'#'+selected.id:'粘贴标签')}}</small></div><div class="settings-body"><details v-for="(name,key) in tagSections" open><summary><strong>{{ui(name)}}</strong><small>{{ui(sections[key].length)}}</small><button class="icon-button" :title="ui('复制'+name)" @click.stop.prevent="copy(sections[key].map(animaTag).join(', '))"><Copy :size="14"/></button></summary><div class="split-tags"><span v-for="tag in sections[key]" :key="tag"><span>{{animaTag(tag)}}<small v-if="prefs.liveTranslation" class="split-tag-translation">{{tagExplanation(tag)}}</small></span><select :value="key" @change="moveTag(tag,$event.target.value)" :aria-label="ui('调整'+tag+'的分类')"><option v-for="(title,category) in tagSections" :value="category">{{ui(title)}}</option></select></span><small v-if="!sections[key].length">{{ui("暂无")}}</small></div></details></div></section></aside></div></template>
